package migrate

import (
	"database/sql"
	"fmt"
)

// Run adds the orders.status column and backfills it.
//
// Run is safe to rerun after a crash at any point: the column is only added
// if missing, and the backfill only touches orders whose status is still NULL,
// writing each order's event and status in one transaction.
func Run(db *sql.DB) error {
	// Probe for the column instead of using ADD COLUMN IF NOT EXISTS, which
	// SQLite and MySQL don't support. If the probe fails for another reason,
	// the ALTER below fails too and surfaces the real error.
	if _, err := db.Exec(`SELECT status FROM orders WHERE 1 = 0`); err != nil {
		if _, err := db.Exec(`ALTER TABLE orders ADD COLUMN status TEXT`); err != nil {
			return fmt.Errorf("add column: %w", err)
		}
	}

	tx, err := db.Begin()
	if err != nil {
		return fmt.Errorf("begin backfill: %w", err)
	}
	defer tx.Rollback()

	// A previous run may have inserted an order's event and crashed before
	// setting its status, so skip orders that already have the event.
	if _, err := tx.Exec(`
		INSERT INTO order_events (order_id, kind)
		SELECT o.id, 'backfilled' FROM orders o
		WHERE o.status IS NULL
		  AND NOT EXISTS (
		    SELECT 1 FROM order_events e
		    WHERE e.order_id = o.id AND e.kind = 'backfilled'
		  )`); err != nil {
		return fmt.Errorf("backfill events: %w", err)
	}
	if _, err := tx.Exec(`UPDATE orders SET status = 'open' WHERE status IS NULL`); err != nil {
		return fmt.Errorf("backfill status: %w", err)
	}
	return tx.Commit()
}

