cd /tmp && rm -f mig.db && sqlite3 mig.db <<'EOF'
CREATE TABLE orders (id INTEGER PRIMARY KEY);
CREATE TABLE order_events (order_id INT, kind TEXT);
INSERT INTO orders VALUES (1),(2),(3),(4);
-- simulate crash: ALTER done, order 1 fully done, order 2 event-only, 3/4 untouched
ALTER TABLE orders ADD COLUMN status TEXT;
INSERT INTO order_events VALUES (1,'backfilled'),(2,'backfilled');
UPDATE orders SET status='open' WHERE id=1;
EOF
run() { sqlite3 mig.db "SELECT status FROM orders WHERE 1 = 0" 2>/dev/null || sqlite3 mig.db "ALTER TABLE orders ADD COLUMN status TEXT"
sqlite3 mig.db "BEGIN; INSERT INTO order_events (order_id, kind) SELECT o.id, 'backfilled' FROM orders o WHERE o.status IS NULL AND NOT EXISTS (SELECT 1 FROM order_events e WHERE e.order_id = o.id AND e.kind = 'backfilled'); UPDATE orders SET status = 'open' WHERE status IS NULL; COMMIT;"; }
run && run
sqlite3 mig.db "SELECT id, status FROM orders; SELECT order_id, count(*) FROM order_events GROUP BY order_id;"
echo "--- fresh db"; rm mig.db; sqlite3 mig.db "CREATE TABLE orders (id INTEGER PRIMARY KEY); CREATE TABLE order_events (order_id INT, kind TEXT); INSERT INTO orders VALUES (1),(2);"
run && run; sqlite3 mig.db "SELECT id, status FROM orders; SELECT order_id, count(*) FROM order_events GROUP BY order_id;"

